// LC 438，输入仅小写字母。窗口长度恒为 p.length()，合法条件是 26 槽与 p 完全相等。
// 换 567：equals 成立立刻 return true，扫完 return false。
// 出现大写或非字母时改成 int[128]，下标直接用字符，不要减 'a'。
static java.util.List<Integer> findAnagrams(String s, String p) {
    java.util.List<Integer> ans = new java.util.ArrayList<>();
    int n = s.length();
    int m = p.length();
    if (m == 0 || n < m) {
        return ans;
    }
    int[] need = new int[26];
    int[] window = new int[26];
    for (int i = 0; i < m; i++) {
        need[p.charAt(i) - 'a']++;
    }
    for (int i = 0; i < n; i++) {
        window[s.charAt(i) - 'a']++;
        if (i >= m) {
            window[s.charAt(i - m) - 'a']--; // 右端进来一个，左端必须出去一个
        }
        if (i >= m - 1 && java.util.Arrays.equals(window, need)) {
            ans.add(i - m + 1);
        }
    }
    return ans;
}

